import{_ as a,o as n,a as p,b as t}from"./app.UgfkfLuP.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"数据重排","link":"/api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/data_reorder"},{"text":"unpack","link":"/api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/unpack"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/unpack.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/unpack.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793005388000}'),l={name:"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/unpack.md"};function e(c,s,r,o,i,d){return n(),p("div",null,[...s[0]||(s[0]=[t(`<div><article class="markdown-body"><h1>unpack</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_compute_sel.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p>选取源寄存器的低半部分或高半部分，将其中各元素的位宽扩展为原来的两倍，按原顺序写入结果寄存器。</p><ul><li>无符号整型执行零扩展，高位补0。</li><li>有符号整型执行符号扩展，保持元素的符号。</li><li>bool类型将所选半部分中的每个比特扩展为两个比特，低位为原比特，高位补0。</li></ul><p>本接口仅在AIV上生效。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">high_low_part</span><span class="w"> </span><span class="n">part</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">high_low_part</span><span class="o">::</span><span class="n">low</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">decltype</span><span class="p">(</span><span class="k">auto</span><span class="p">)</span><span class="w"> </span><span class="n">unpack</span><span class="p">(</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src</span><span class="p">);</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>part</td><td>源数据的选取位置。<code>high_low_part::low</code>表示选取源寄存器的低半部分，<code>high_low_part::high</code>表示选取高半部分。默认值为<code>high_low_part::low</code>。</td></tr><tr><td>T</td><td>源寄存器的元素类型，支持的类型请参见<a href="#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 函数参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>src</td><td>输入</td><td>源操作数，类型为<a href="../reg_tensor/reg_tensor.html">reg_tensor&lt;T&gt;</a>。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><table><thead><tr><th>T</th><th>返回值类型</th></tr></thead><tbody><tr><td>bool</td><td>reg_tensor&lt;bool&gt;</td></tr><tr><td>int8_t</td><td>reg_tensor&lt;int16_t&gt;</td></tr><tr><td>uint8_t</td><td>reg_tensor&lt;uint16_t&gt;</td></tr><tr><td>int16_t</td><td>reg_tensor&lt;int32_t&gt;</td></tr><tr><td>uint16_t</td><td>reg_tensor&lt;uint32_t&gt;</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回类型由T推导，具体映射见数据类型表。<code>reg</code>保存扩展后的数据，<code>mask</code>直接复制<code>src.mask</code>。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><code>part</code>仅支持<code>high_low_part::low</code>和<code>high_low_part::high</code>。</li><li>扩展计算不使用<code>src.mask</code>屏蔽元素，须保证源寄存器所选半部分的数据已初始化。</li><li>返回值的<code>mask</code>不会根据源数据选取位置及目的元素位宽进行转换。在后续操作使用掩码前，须重新绑定适合结果类型和有效位置的掩码，参见<a href="../reg_tensor/reg_tensor.html#with_mask">with_mask</a>。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下代码片段在VF中调用。<code>src.reg</code>的低半部分已初始化，将其符号扩展为int16_t，并为结果绑定int16_t类型的全有效掩码。示例使用的掩码接口请参见<a href="../mask_reg_compute/all_mask.html">all_mask</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="kt">int16_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">unpack_example</span><span class="p">(</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">src</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="p">());</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">result</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">unpack</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">high_low_part</span><span class="o">::</span><span class="n">low</span><span class="o">&gt;</span><span class="p">(</span><span class="n">src</span><span class="p">);</span>
<span class="w">    </span><span class="n">result</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="kt">int16_t</span><span class="o">&gt;</span><span class="p">());</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">result</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const g=a(l,[["render",e]]);export{_ as __pageData,g as default};
